// ── Helpers
function fmtDate(d) {
  if(!d) return "--";
  try { return new Date(d+"T12:00:00").toLocaleDateString("pt-BR"); } catch { return d||"--"; }
}

function getWeekLabel(dateStr) {
  if(!dateStr) return "";
  try {
    const d = new Date(dateStr+"T12:00:00");
    const months = ["Janeiro","Fevereiro","Março","Abril","Maio","Junho",
                    "Julho","Agosto","Setembro","Outubro","Novembro","Dezembro"];
    const year = d.getFullYear();
    const monthIdx = d.getMonth();
    const day = d.getDate();
    // Find first Sunday of the month
    let firstSun = new Date(year, monthIdx, 1);
    while(firstSun.getDay() !== 0) firstSun.setDate(firstSun.getDate()+1);
    const firstSunDay = firstSun.getDate();
    const diff = day - firstSunDay;
    let week;
    if(diff < 0) {
      week = 1;
    } else {
      week = Math.min(Math.floor(diff/7) + 1, 5);
    }
    return "S"+week+" "+months[monthIdx];
  } catch { return ""; }
}

export function getTheme(projectId) {
  return THEMES[projectId] || THEMES["P601"];
}

function calcHealthPct(project, state) {
  if(!project?.categories||!state) return 100;
  let total=0, ok=0;
  for(const cat of project.categories) {
    const s = state[cat.id]; if(!s) continue;
    if(cat.type==="maintenance"||cat.type==="notes") continue;
    if(cat.type==="single") { total++; if(!s.status||s.status==="ok") ok++; }
    else if(cat.type==="items"&&Array.isArray(s)) {
      s.forEach(v=>{ total++; if(!v.status||v.status==="ok") ok++; });
    } else if(cat.type==="count") {
      const t=s.total??cat.total??0, inop=s.inoper??0;
      total+=t; ok+=(t-inop);
    }
  }
  return total>0?Math.round((ok/total)*100):100;
}

function stLabel(st) { return !st||st==="ok"?"OK":st==="partial"?"PARCIAL":"INOPERANTE"; }
// Status colors ALWAYS fixed — never use theme color for status
function stColor(st) { return !st||st==="ok"?"#15803d":st==="partial"?"#d97706":"#dc2626"; }
function stBg(st)    { return !st||st==="ok"?"#dcfce7":st==="partial"?"#fef3c7":"#fee2e2"; }
// Bar color by percentage — always fixed
function barColor(pct) {
  if(pct===100) return "#15803d"; // green
  if(pct>0)    return "#d97706"; // yellow
  return "#dc2626";               // red
}
function barTextColor(pct) {
  if(pct===100) return "#15803d";
  if(pct>0)    return "#d97706";
  return "#dc2626";
}
// Critical threshold: > 30 days
const CRITICAL_DAYS = 150;  // Critério 1: > 150 dias em aberto
const VOLUME_THRESHOLD = 8;  // Critério 2: > 8 subitens com falha no mesmo sistema
const COMPACT_THRESHOLD = 10;  // > 10 itens com falha no mesmo sistema → tabela compacta interna
function isCritical(diasAberto) { return diasAberto !== null && diasAberto > CRITICAL_DAYS; }

